import { useMemo, useState } from "react";
import { Form } from "./form.setup";
// generated by `paraglide-js compile` from docs/i18n-messages/{locale}.json
import { m } from "./paraglide/messages.js";

type Locale = "en" | "vi";
type Message = (inputs: Record<string, unknown>, options: { locale: Locale }) => string;

// Paraglide messages are functions, not string keys: config labels use message
// names, and `t` looks them up (an unknown name comes back as is).
const translator = (locale: Locale) => (key: string, params?: Record<string, unknown>) => {
  const message = (m as unknown as Record<string, Message | undefined>)[key];
  return message ? message(params ?? {}, { locale }) : key;
};

export default function EgI18nParaglide() {
  const [locale, setLocale] = useState<Locale>("en");
  const t = useMemo(() => translator(locale), [locale]);
  return (
    <Form
      i18nConfig={{
        t,
        validationTranslation: { required: "validation_required", minLength: "validation_min_length" },
        translateProps: ["placeholder"],
      }}
      config={{
        username: {
          type: "text",
          label: "username_label",
          description: "username_description",
          props: { placeholder: "username_placeholder" },
          rules: { required: true, minLength: 3 },
        },
      }}
    >
      <button type="button" onClick={() => setLocale(locale === "en" ? "vi" : "en")}>
        {locale === "en" ? "Tiếng Việt" : "English"}
      </button>
      <button type="submit">Submit</button>
    </Form>
  );
}
